INSERT INTO curriculum_chunks (id, topic_id, content, source_ref, version, status, embedding, created_at, updated_at) 
VALUES ('22b9c424-8d5a-4cd0-92fa-af50304927dd', '00000000-0000-4000-8000-000000000400', 'Defence of National Sovereignty, 1871-1896 Learning outcomes of the lesson At the end of this lesson, the students will be able to: • explain the causes of the British military expedition led by General Napier; • recognise the attempts of Egyptians to dominate the Nile basin ; • unravel the results of the Hewett Treaty; • pinpoint the causes and effects of the battle of Adwa ; • appreciate the heroic resistance of the Ethiopian people against foreign aggression. • Identify the foreign powers who attempted to violate Ethiopia’s territorial integrity in the second half of 19 th C. • Mention at least four battles where Ethiopia scored decisive victories over foreign aggressors in the second half of 19 th C. Brainstorming The second half of the nineteenth century was a period during which the survival of Ethiopian independence was put to the utmost test. Emperor Tewodros’s modernization drive emanated mainly from the understanding of this danger to Ethiopia. He needed the technical support of Europe, particularly that of Britain, both against what he considered to be the main threat to Ethiopia, namely Egypt, and to assist him in his goal of modernizing the country. As a result, in 1862, Tewodros sent a letter to Queen Victoria of Great Britain requesting military assistance through Consul Cameron. Cameron came back to Ethiopia via Egypt without any response. Tewodros held Cameron directly responsible for the lack of response to his letter of 1862 to Queen Victoria of England. He also suspected him of conspiring with the “Turks”, i.e. the Egyptians, against him. On learning about the imprisonment of the Europeans, Queen Victoria sent a letter through Hormuzd RAssem, which did not satisfy Tewodros. After some communications, the British parliament decided to take military action.', 'G10-History-STB-2023-web.pdf p.1', '2026.1', 'published', '[-0.00096313516,0.021487623,-0.014791919,-0